const clearFilterButton = document.createElement('button');
clearFilterButton.textContent = 'Clear Filter';
document.body.appendChild(clearFilterButton);
clearFilterButton.addEventListener('click', function () {
  field.value = '';
  narrowList();
});
// FACT: a button with text 'Clear Filter' is created
// FACT: a click event handler is attached to the button
// when the button is clicked: #text is empty; every item in the list is visible again. Ensure typing in the filter still narrows the list.

